CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `orderId` varchar(20) NOT NULL,
  `customerName` varchar(100) NOT NULL,
  `customerEmail` varchar(100) DEFAULT NULL,
  `customerPhone` varchar(20) DEFAULT NULL,
  `customerAddress` text,
  `orderStatus` varchar(30) DEFAULT 'Pending',
  `productCode` varchar(50) NOT NULL,
  `productName` varchar(100) NOT NULL,
  `fabricType` varchar(50) DEFAULT NULL,
  `quantity` int NOT NULL,
  `unitOfMeasure` varchar(20) DEFAULT NULL,
  `unitPrice` decimal(10,2) NOT NULL,
  `orderDate` date DEFAULT (curdate()),
  `deliveryDate` date DEFAULT NULL,
  `paymentStatus` varchar(30) DEFAULT 'Unpaid',
  `paymentMode` varchar(30) DEFAULT NULL,
  `dispatchedFrom` varchar(100) DEFAULT NULL,
  `trackingId` varchar(100) DEFAULT NULL,
  `remarks` text,
  `createdAt` datetime DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updatedBy` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `orderId_UNIQUE` (`orderId`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


